public sealed class HoverVisual {
 readonly DrawingVisual cross,box;readonly TranslateTransform position=new TranslateTransform();string key;double width,height;public int TextLayouts;public HoverVisual(DrawingVisual a,DrawingVisual b){cross=a;box=b;box.Transform=position;}
 public void Clear(){using(var dc=cross.RenderOpen()){}box.Opacity=0;}
 public void Draw(FrameworkElement owner,HoverReading reading,Point mouse,Rect plot,long from,long to){if(reading==null){Clear();return;}double x=plot.Left+plot.Width*Math.Max(0,Math.Min(1,(reading.TargetUtc.Ticks-from)/(double)Math.Max(1,to-from)));using(var dc=cross.RenderOpen()){dc.DrawLine(new Pen(Theme.Teal,1){DashStyle=DashStyles.Dash},new Point(x,plot.Top),new Point(x,plot.Bottom));if(!reading.Gap&&!double.IsNaN(reading.Value)){double px=plot.Left+plot.Width*(reading.SampleUtc.Ticks-from)/(double)Math.Max(1,to-from),py=plot.Top+plot.Height*(1-Math.Max(0,Math.Min(100,reading.Value))/100);dc.DrawRectangle(Theme.Green,new Pen(Theme.Ink,1),new Rect(px-3,py-3,6,6));}}
 double dpi=VisualTreeHelper.GetDpi(owner).PixelsPerDip;string text=reading.Text;string next=text+"/"+owner.ActualWidth+"/"+owner.ActualHeight+"/"+dpi+"/"+Theme.Name;if(key!=next){key=next;TextLayouts++;var formatted=new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface(Theme.Chinese.Source),13,Theme.Ink,dpi){MaxTextWidth=Math.Max(30,Math.Min(290,owner.ActualWidth-24)),MaxTextHeight=Math.Max(24,owner.ActualHeight-24),Trimming=TextTrimming.CharacterEllipsis};width=formatted.Width+20;height=formatted.Height+16;using(var dc=box.RenderOpen()){dc.DrawRectangle(Theme.Surface,new Pen(Theme.Teal,1),new Rect(0,0,width,height));dc.DrawText(formatted,new Point(10,8));}}
 position.X=Math.Max(2,Math.Min(owner.ActualWidth-width-2,mouse.X+14));position.Y=Math.Max(2,Math.Min(owner.ActualHeight-height-2,mouse.Y-height-10));box.Opacity=1;
 }
}
public abstract class ResourceChart : FrameworkElement,IFrameMotion {
 readonly VisualCollection visuals;protected readonly DrawingVisual axes=new DrawingVisual(),series=new DrawingVisual(),arrival=new DrawingVisual(),selection=new DrawingVisual(),cross=new DrawingVisual(),tip=new DrawingVisual();readonly HoverVisual painter;readonly DispatcherTimer hoverTimer;Point? pending,mouse;double lastHover;string axisKey;bool moving;double started,shift;Point end;readonly TranslateTransform scroll=new TranslateTransform();public int BaseRebuilds,AxisRebuilds,HoverRepaints,MotionFrames;public int TooltipLayouts{get{return painter.TextLayouts;}}public bool IsChartAnimating{get{return moving;}}public HoverReading HoverReading;public string HoverText{get{return HoverReading==null?"":HoverReading.Text;}}
 protected abstract Rect Plot{get;}protected abstract long PlotFrom{get;}protected abstract long PlotTo{get;}protected abstract string AxesKey{get;}
 protected abstract void DrawAxes(DrawingContext dc);protected abstract void DrawSeries(DrawingContext dc);protected abstract HoverReading FindHover(Point point);protected virtual void DrawSelection(DrawingContext dc){}
 protected ResourceChart(){ClipToBounds=true;visuals=new VisualCollection(this){axes,series,arrival,selection,cross,tip};series.Transform=scroll;painter=new HoverVisual(cross,tip);Cursor=Cursors.Cross;hoverTimer=new DispatcherTimer(DispatcherPriority.Input){Interval=TimeSpan.FromMilliseconds(16)};hoverTimer.Tick+=(s,e)=>{hoverTimer.Stop();if(pending.HasValue){var p=pending.Value;pending=null;HoverAt(p);}};MouseMove+=(s,e)=>QueueHover(e.GetPosition(this));MouseLeave+=(s,e)=>ClearHover();Unloaded+=(s,e)=>{EndMotion();ClearHover();};IsVisibleChanged+=(s,e)=>{if(!IsVisible){EndMotion();ClearHover();}};}
 protected override int VisualChildrenCount{get{return visuals.Count;}}protected override Visual GetVisualChild(int index){return visuals[index];}
 public void QueueHover(Point point){pending=point;if(MotionClock.Now-lastHover>=0.016){pending=null;HoverAt(point);}else if(!hoverTimer.IsEnabled)hoverTimer.Start();}
 public void HoverAt(Point point){lastHover=MotionClock.Now;mouse=point;EndMotion();PaintHover();}
 public void ClearHover(){pending=null;mouse=null;hoverTimer.Stop();HoverReading=null;painter.Clear();}
 void PaintHover(){HoverReading=mouse.HasValue?FindHover(mouse.Value):null;HoverRepaints++;if(mouse.HasValue)painter.Draw(this,HoverReading,mouse.Value,Plot,PlotFrom,PlotTo);else painter.Clear();}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);dc.DrawRectangle(Brushes.Transparent,null,new Rect(0,0,Math.Max(0,ActualWidth),Math.Max(0,ActualHeight)));BaseRebuilds++;string next=AxesKey+"/"+ActualWidth+"/"+ActualHeight+"/"+Theme.Name+"/"+VisualTreeHelper.GetDpi(this).PixelsPerDip;if(axisKey!=next){axisKey=next;AxisRebuilds++;using(var drawing=axes.RenderOpen())DrawAxes(drawing);}series.Clip=new RectangleGeometry(new Rect(Plot.Left-4,Plot.Top-4,Plot.Width+8,Plot.Height+8));arrival.Clip=new RectangleGeometry(new Rect(Plot.Left-10,Plot.Top-10,Plot.Width+20,Plot.Height+20));using(var drawing=series.RenderOpen())DrawSeries(drawing);UpdateSelection();if(mouse.HasValue)PaintHover();}
 public void UpdateSelection(){using(var dc=selection.RenderOpen())DrawSelection(dc);}
 protected void Arrival(Point endpoint,double offset){EndMotion();if(mouse.HasValue||!IsLoaded||!IsVisible||!Motion.Enabled)return;end=endpoint;shift=Math.Max(0,Math.Min(24,offset));started=MotionClock.Now;moving=true;MotionClock.Add(this);Frame(started);}
 public bool Frame(double now){if(!moving)return false;if(!IsLoaded||!IsVisible||!Motion.Enabled||mouse.HasValue){EndMotion();return false;}double t=Math.Max(0,(now-started)/0.54);if(t>=1){EndMotion();return false;}double ease=Motion.Ease(t);scroll.X=shift*(1-ease);double radius=3+7*ease;using(var dc=arrival.RenderOpen()){dc.PushOpacity(0.38*(1-ease));dc.DrawRectangle(null,new Pen(Theme.Teal,1),new Rect(end.X+scroll.X-radius,end.Y-radius,radius*2,radius*2));dc.Pop();}MotionFrames++;return true;}
 protected void EndMotion(){moving=false;MotionClock.Remove(this);scroll.X=0;using(var dc=arrival.RenderOpen()){};}
 protected void Label(DrawingContext dc,string text,double x,double y,Brush color){dc.DrawText(new FormattedText(text,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface(Theme.Chinese.Source),11,color,VisualTreeHelper.GetDpi(this).PixelsPerDip),new Point(x,y));}
 protected static void Geometry(DrawingContext dc,IEnumerable<Tuple<Point,bool>> vertices){var path=new StreamGeometry();using(var context=path.Open()){bool first=true;foreach(var vertex in vertices){if(first||vertex.Item2)context.BeginFigure(vertex.Item1,false,false);else context.LineTo(vertex.Item1,true,false);first=false;}}path.Freeze();dc.DrawGeometry(null,new Pen(Theme.Green,2),path);}
}
public class TrendChart : ResourceChart {
 public List<ResourceSample> Data=new List<ResourceSample>();public bool Memory;public int Interval=5;DateTime plotEnd=DateTime.UtcNow;long lastTick;bool lastMemory;
 protected override Rect Plot{get{return new Rect(48,14,Math.Max(1,ActualWidth-60),Math.Max(1,ActualHeight-44));}}protected override long PlotFrom{get{return plotEnd.AddMinutes(-5).Ticks;}}protected override long PlotTo{get{return plotEnd.Ticks;}}protected override string AxesKey{get{return "live";}}
 protected override void DrawAxes(DrawingContext dc){var plot=Plot;for(int i=0;i<=4;i++){double y=plot.Top+plot.Height*i/4;dc.DrawLine(new Pen(Theme.Line,1),new Point(plot.Left,y),new Point(plot.Right,y));Label(dc,(100-i*25)+"%",0,y-7,Theme.Muted);}Label(dc,"−5 分钟",plot.Left,plot.Bottom+12,Theme.Muted);Label(dc,"−2分30秒",plot.Left+plot.Width/2-28,plot.Bottom+12,Theme.Muted);Label(dc,"现在",plot.Right-26,plot.Bottom+12,Theme.Muted);}
 protected override void DrawSeries(DrawingContext dc){plotEnd=DateTime.UtcNow;var plot=Plot;if(Data==null||Data.Count==0){EndMotion();Label(dc,"等待第一个有效采样点…",plot.Left+18,plot.Top+plot.Height/2,Theme.Muted);lastTick=0;return;}var vertices=new List<Tuple<Point,bool>>();DateTime previous=DateTime.MinValue;bool broken=true;ResourceSample latest=null;foreach(var item in Data){double value=Memory?item.Memory:item.Cpu;double age=(plotEnd-item.Time).TotalSeconds;if(age>300||age<0||double.IsNaN(value)){broken=true;continue;}var p=new Point(plot.Left+plot.Width*(1-age/300),plot.Top+plot.Height*(1-Math.Max(0,Math.Min(100,value))/100));vertices.Add(Tuple.Create(p,broken||(item.Time-previous).TotalSeconds>Math.Max(Interval*3,15)));broken=false;previous=item.Time;latest=item;}Geometry(dc,vertices);if(vertices.Count>0){var end=vertices[vertices.Count-1].Item1;dc.DrawRectangle(Theme.Green,null,new Rect(end.X-3,end.Y-3,6,6));long tick=latest.Time.Ticks;bool arrived=lastTick>0&&tick>lastTick&&Memory==lastMemory&&(tick-lastTick)<TimeSpan.FromSeconds(Math.Max(Interval*3,15)).Ticks;double shift=arrived?plot.Width*(tick-lastTick)/(double)TimeSpan.FromMinutes(5).Ticks:0;lastMemory=Memory;lastTick=tick;if(arrived)Arrival(end,shift);else EndMotion();}else EndMotion();}
 protected override HoverReading FindHover(Point point){var plot=Plot;if(!plot.Contains(point)||Data==null)return null;long tick=PlotFrom+(long)((PlotTo-PlotFrom)*(point.X-plot.Left)/plot.Width);int i=ChartHover.Nearest(Data,tick,x=>x.Time.Ticks);if(i<0)return null;var item=Data[i];double value=Memory?item.Memory:item.Cpu;bool gap=Math.Abs(tick-item.Time.Ticks)>TimeSpan.FromSeconds(Math.Max(Interval*1.5,3)).Ticks||item.Time.Ticks<PlotFrom||double.IsNaN(value);return new HoverReading{TargetUtc=new DateTime(tick,DateTimeKind.Utc),SampleUtc=DateTime.SpecifyKind(item.Time,DateTimeKind.Utc),Value=value,Metric=Memory?"内存":"CPU",Gap=gap};}
}
public class HistoryChart : ResourceChart {
 public List<ArchiveDot> Data=new List<ArchiveDot>();public long From,To;long selected;public long Selected{get{return selected;}set{selected=value;UpdateSelection();}}public Action<long> Select;public bool HasGpu=true;bool dragging;public string Metric="CPU";public List<ArchivePoint> HoverPoints=new List<ArchivePoint>();
 protected override Rect Plot{get{return new Rect(48,18,Math.Max(1,ActualWidth-64),Math.Max(1,ActualHeight-54));}}protected override long PlotFrom{get{return From;}}protected override long PlotTo{get{return To;}}protected override string AxesKey{get{return From+"/"+To;}}
 public HistoryChart(){MouseLeftButtonDown+=(s,e)=>{dragging=true;CaptureMouse();Pick(e.GetPosition(this).X);};MouseMove+=(s,e)=>{if(dragging)Pick(e.GetPosition(this).X);};MouseLeftButtonUp+=(s,e)=>{dragging=false;ReleaseMouseCapture();};LostMouseCapture+=(s,e)=>dragging=false;}
 void Pick(double x){double ratio=Math.Max(0,Math.Min(1,(x-48)/Math.Max(1,ActualWidth-64)));if(Select!=null)Select(From+(long)((To-From)*ratio));}
 protected override void DrawAxes(DrawingContext dc){var p=Plot;for(int i=0;i<=4;i++){double y=p.Top+p.Height*i/4;dc.DrawLine(new Pen(Theme.Line,1),new Point(p.Left,y),new Point(p.Right,y));Label(dc,(100-i*25)+"%",0,y-7,Theme.Muted);}for(int i=0;i<=4;i++){long tick=From+(long)((To-From)*(i/4.0));var when=new DateTime(Math.Max(0,Math.Min(DateTime.MaxValue.Ticks,tick)),DateTimeKind.Utc).ToLocalTime();string text=(To-From)>TimeSpan.FromHours(24).Ticks?when.ToString("MM-dd HH:mm"):when.ToString("HH:mm:ss");double x=p.Left+p.Width*i/4;dc.DrawLine(new Pen(Theme.Line,1),new Point(x,p.Bottom),new Point(x,p.Bottom+4));Label(dc,text,x-(i==0?0:i==4?70:34),p.Bottom+13,Theme.Muted);}}
 protected override void DrawSeries(DrawingContext dc){var p=Plot;var vertices=new List<Tuple<Point,bool>>();foreach(var dot in Data){if(dot.T<From||dot.T>To||double.IsNaN(dot.Value))continue;vertices.Add(Tuple.Create(new Point(p.Left+p.Width*(dot.T-From)/(double)Math.Max(1,To-From),p.Top+p.Height*(1-Math.Max(0,Math.Min(100,dot.Value))/100)),dot.Break));}Geometry(dc,vertices);foreach(var v in vertices.Where(x=>x.Item2))dc.DrawRectangle(Theme.Green,null,new Rect(v.Item1.X-2,v.Item1.Y-2,4,4));if(Data.Count==0)Label(dc,HasGpu?"这个时间范围内没有有效采样":"这个时间范围没有 NVIDIA GPU 数据",p.Left+24,p.Top+p.Height/2-7,Theme.Muted);}
 protected override void DrawSelection(DrawingContext dc){if(Selected>=From&&Selected<=To&&To>From){var p=Plot;double x=p.Left+p.Width*(Selected-From)/(double)(To-From);dc.DrawLine(new Pen(Theme.Teal,1),new Point(x,p.Top),new Point(x,p.Bottom));}}
 protected override HoverReading FindHover(Point point){var p=Plot;if(!p.Contains(point)||To<=From)return null;long tick=From+(long)((To-From)*(point.X-p.Left)/p.Width);int i=ChartHover.Nearest(HoverPoints,tick,x=>x.T);if(i<0)return null;var item=HoverPoints[i];double value=item.Value(Metric);bool gap=Math.Abs(tick-item.T)>TimeSpan.FromSeconds(Math.Max(item.Interval*1.5,3)).Ticks||double.IsNaN(value)||!string.IsNullOrEmpty(item.Error);return new HoverReading{TargetUtc=new DateTime(tick,DateTimeKind.Utc),SampleUtc=new DateTime(item.T,DateTimeKind.Utc),Metric=Metric,Value=value,Gap=gap,Error=item.Error};}
}
